mapper.select:
SELECT distinct a.drug_id, a.drug_name_chinese, a.disease_name_chinese,  a.relationship_category_chinese, a.annotation_chinese, a.evidence_phase_id, a.evidence_phase_chinese 
FROM nkb_variant_treatment_annotation a join panel_display t on t.evidence_cancer_id  = a.approved_disease_id  and t.is_primary='Y'
where a.relationship_category = 'Sensitive' and a.evidence_phase_id is not null and a.gene_variant_id = #{gene_variant_id} and t.primary_cancer_id = #{primary_cancer_id}
order by a.evidence_phase_id desc;

SELECT distinct a.drug_id, a.drug_name_chinese, a.disease_name_chinese,  a.relationship_category_chinese, a.annotation_chinese, a.evidence_phase_id, a.evidence_phase_chinese 
FROM nkb_variant_treatment_annotation a join panel_display t on t.evidence_cancer_id  = a.approved_disease_id  and t.is_primary='Y'
where a.relationship_category = 'Sensitive' and a.evidence_phase_id is not null and a.evidence_phase_id != 12 and a.gene_variant_id = #{gene_variant_id} and t.primary_cancer_id = #{primary_cancer_id}
order by a.evidence_phase_id desc;

