FROM nkb_variant_treatment_annotation a join panel_display t on t.evidence_cancer_id  = a.approved_disease_id  and t.is_primary='Y'
where a.relationship_category = 'Sensitive' and a.evidence_phase_id is not null and a.evidence_phase_id != 12 and a.approved_disease_id is not null and a.gene_variant_id = #{gene_variant_id} and t.primary_cancer_id = #{primary_cancer_id}
order by a.evidence_phase_id desc;
